css:
.cfo-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #f0f4f8 0%, #e2e8f0 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.cfo-sim-container .cfo-sim-header {
    background: linear-gradient(135deg, #1a2332 0%, #2c3e50 100%);
    color: white;
    padding: 30px;
    border-radius: 16px;
    margin-bottom: 24px;
    box-shadow: 0 8px 24px rgba(26,35,50,0.25);
    text-align: center;
}

.cfo-sim-container .cfo-sim-header h1 {
    margin: 0 0 6px 0;
    font-size: 2rem;
    font-weight: 700;
    letter-spacing: -0.5px;
}

.cfo-sim-container .cfo-sim-subtitle {
    margin: 0;
    font-size: 1rem;
    opacity: 0.85;
    font-weight: 400;
}

.cfo-sim-container .cfo-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    color: #4a5568;
    margin-bottom: 20px;
    font-weight: 600;
}

.cfo-sim-container .cfo-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.cfo-sim-container .cfo-sim-status-card {
    background: white;
    border-radius: 12px;
    padding: 20px 16px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08);
    text-align: center;
    transition: transform 0.2s ease;
    border-top: 4px solid #cbd5e0;
}

.cfo-sim-container .cfo-sim-status-card:hover {
    transform: translateY(-3px);
}

.cfo-sim-container .cfo-sim-card-cash { border-top-color: #2b6cb0; }
.cfo-sim-container .cfo-sim-card-rating { border-top-color: #2f855a; }
.cfo-sim-container .cfo-sim-card-wacc { border-top-color: #9b2c2c; }
.cfo-sim-container .cfo-sim-card-score { border-top-color: #b7791f; }

.cfo-sim-container .cfo-sim-label {
    color: #718096;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.cfo-sim-container .cfo-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #2d3748;
}

.cfo-sim-container .cfo-sim-briefing {
    background: white;
    border-left: 5px solid #2b6cb0;
    border-radius: 0 12px 12px 0;
    padding: 20px 24px;
    margin-bottom: 24px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.cfo-sim-container .cfo-sim-briefing h3 {
    margin: 0 0 10px 0;
    color: #1a2332;
    font-size: 1.15rem;
}

.cfo-sim-container .cfo-sim-briefing p {
    margin: 0;
    color: #4a5568;
    line-height: 1.6;
    font-size: 0.95rem;
}

.cfo-sim-container .cfo-sim-controls {
    background: white;
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 20px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.cfo-sim-container .cfo-sim-controls h4 {
    margin: 0 0 16px 0;
    color: #2d3748;
    font-size: 1.1rem;
    border-bottom: 2px solid #e2e8f0;
    padding-bottom: 10px;
}

.cfo-sim-container .cfo-sim-data-box {
    background: #f7fafc;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    padding: 14px 18px;
    margin-bottom: 18px;
    font-size: 0.9rem;
    color: #4a5568;
    line-height: 1.7;
}

.cfo-sim-container .cfo-sim-data-box p {
    margin: 0 0 4px 0;
}

.cfo-sim-container .cfo-sim-input-group {
    margin-bottom: 16px;
}

.cfo-sim-container .cfo-sim-input-group label {
    display: block;
    font-weight: 600;
    color: #4a5568;
    margin-bottom: 6px;
    font-size: 0.9rem;
}

.cfo-sim-container .cfo-sim-input-group .form-control {
    border: 2px solid #e2e8f0;
    border-radius: 8px;
    padding: 10px 14px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.cfo-sim-container .cfo-sim-input-group .form-control:focus {
    border-color: #2b6cb0;
    box-shadow: 0 0 0 3px rgba(43,108,176,0.15);
}

.cfo-sim-container .cfo-sim-wacc-preview {
    background: linear-gradient(135deg, #ebf8ff 0%, #e6fffa 100%);
    border: 2px solid #bee3f8;
    border-radius: 10px;
    padding: 14px 20px;
    text-align: center;
    font-size: 1.1rem;
    margin-top: 12px;
}

.cfo-sim-container .cfo-sim-wacc-preview strong {
    font-size: 1.5rem;
    color: #2b6cb0;
    margin-left: 8px;
}

.cfo-sim-container .cfo-sim-instruction {
    color: #4a5568;
    font-size: 0.92rem;
    line-height: 1.5;
    margin-bottom: 16px;
    padding: 10px 14px;
    background: #fffff0;
    border-radius: 8px;
    border: 1px solid #fefcbf;
}

.cfo-sim-container .cfo-sim-opportunities {
    margin-bottom: 18px;
}

.cfo-sim-container .cfo-sim-opp-card {
    background: #f7fafc;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    padding: 14px 16px;
    margin-bottom: 10px;
    transition: background 0.2s, border-color 0.2s;
}

.cfo-sim-container .cfo-sim-opp-card:hover {
    background: #edf2f7;
    border-color: #a0aec0;
}

.cfo-sim-container .cfo-sim-opp-card label {
    font-weight: 600;
    color: #2d3748;
    cursor: pointer;
    font-size: 0.95rem;
}

.cfo-sim-container .cfo-sim-opp-detail {
    margin-top: 6px;
    padding-left: 24px;
    color: #718096;
    font-size: 0.85rem;
}

.cfo-sim-container .cfo-sim-budget-row {
    background: #ebf8ff;
    border: 1px solid #bee3f8;
    border-radius: 8px;
    padding: 12px 16px;
    font-size: 1rem;
    color: #2b6cb0;
    text-align: center;
    margin-top: 10px;
}

.cfo-sim-container .cfo-sim-budget-row strong {
    font-size: 1.3rem;
    margin-left: 6px;
}

.cfo-sim-container .cfo-sim-credit-model {
    background: #f7fafc;
    border: 2px solid #e2e8f0;
    border-radius: 10px;
    padding: 18px 20px;
    margin-top: 18px;
}

.cfo-sim-container .cfo-sim-credit-model h5 {
    margin: 0 0 14px 0;
    color: #2d3748;
    font-size: 1rem;
}

.cfo-sim-container .cfo-sim-metric-row {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 0;
    border-bottom: 1px solid #edf2f7;
    flex-wrap: wrap;
    font-size: 0.93rem;
}

.cfo-sim-container .cfo-sim-metric-row:last-child {
    border-bottom: none;
}

.cfo-sim-container .cfo-sim-status-ok {
    background: #c6f6d5;
    color: #276749;
    padding: 2px 10px;
    border-radius: 12px;
    font-size: 0.78rem;
    font-weight: 700;
    text-transform: uppercase;
}

.cfo-sim-container .cfo-sim-status-breach {
    background: #fed7d7;
    color: #9b2c2c;
    padding: 2px 10px;
    border-radius: 12px;
    font-size: 0.78rem;
    font-weight: 700;
    text-transform: uppercase;
}

.cfo-sim-container .cfo-sim-threshold {
    color: #a0aec0;
    font-size: 0.82rem;
}

.cfo-sim-container .cfo-sim-rating-result strong {
    font-size: 1.2rem;
    color: #276749;
}

.cfo-sim-container .cfo-sim-disclosure-box {
    background: #fffff0;
    border: 2px solid #fefcbf;
    border-radius: 10px;
    padding: 16px 18px;
    margin: 14px 0;
}

.cfo-sim-container .cfo-sim-disclosure-box label {
    font-weight: 600;
    color: #744210;
    cursor: pointer;
    font-size: 0.93rem;
}

.cfo-sim-container .cfo-sim-note {
    margin: 8px 0 0 24px;
    color: #975a16;
    font-size: 0.83rem;
    line-height: 1.5;
}

.cfo-sim-container .cfo-sim-actions {
    text-align: center;
    margin: 20px 0 24px 0;
}

.cfo-sim-container .cfo-sim-submit-btn {
    background: linear-gradient(135deg, #2b6cb0, #2c5282);
    border: none;
    border-radius: 10px;
    padding: 12px 36px;
    font-size: 1.05rem;
    font-weight: 700;
    letter-spacing: 0.3px;
    box-shadow: 0 4px 12px rgba(43,108,176,0.3);
    transition: transform 0.15s, box-shadow 0.15s;
}

.cfo-sim-container .cfo-sim-submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 16px rgba(43,108,176,0.4);
}

.cfo-sim-container .cfo-sim-undo-btn {
    margin-left: 12px;
    border-radius: 8px;
}

.cfo-sim-container .cfo-sim-history {
    margin-bottom: 24px;
}

.cfo-sim-container .cfo-sim-chart {
    background: white;
    border-radius: 12px;
    padding: 20px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
    min-height: 280px;
}

@media (max-width: 768px) {
    .cfo-sim-container .cfo-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .cfo-sim-container .cfo-sim-header h1 {
        font-size: 1.5rem;
    }
    .cfo-sim-container .cfo-sim-metric-row {
        font-size: 0.85rem;
    }
}
/* EQIL 2026-10-27: focus, motion and debrief (namespaced cfo-sim-) */
.cfo-sim-container select:focus-visible, .cfo-sim-container input:focus-visible, .cfo-sim-container button:focus-visible { outline: 3px solid #1e4e8c; outline-offset: 2px; }
.cfo-sim-container .cfo-sim-status-breach::before { content: "\26A0  "; }
@media (prefers-reduced-motion: reduce) { .cfo-sim-container *, .cfo-sim-cm * { transition: none !important; animation: none !important; } }
.cfo-sim-cm { text-align: left; color: #1a202c; }
.cfo-sim-cm-score { font-size: 1.6rem; margin-bottom: .25rem; }
.cfo-sim-cm-tier { display: inline-block; margin-left: .5rem; padding: .1rem .6rem; border-radius: 4px; background: #1e4e8c; color: #fff; font-size: 1rem; vertical-align: middle; }
.cfo-sim-cm-sub { color: #4a5568; margin: 0 0 .75rem; }
.cfo-sim-cm-kpis { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: .75rem; }
.cfo-sim-cm-kpi { flex: 1 1 120px; border: 1px solid #cbd5e0; border-radius: 6px; padding: 6px 8px; background: #f7fafc; }
.cfo-sim-cm-kpi-l { display: block; font-size: .8rem; color: #4a5568; }
.cfo-sim-cm-h { font-size: 1rem; margin: .75rem 0 .25rem; color: #1a252f; }
.cfo-sim-cm ul, .cfo-sim-cm ol { padding-left: 1.2rem; margin: 0; }
.cfo-sim-cm li { margin-bottom: .35rem; }

