                    brief: 'Calculate the Weighted Average Cost of Capital for Andina Industrial from first principles. The data below contains three deliberate traps that mirror the most common real-world WACC errors. Choose your inputs carefully — every investment decision in subsequent rounds depends on this number.'
                },
                {
                    panel: 'round2Panel',
                    title: 'Round 2: Investment Evaluation',
                    brief: 'Andina has $40M of investable capital from the asset sale plus access to external financing. Five opportunities compete for funding. Select which to pursue, choose your ranking criterion, and decide whether to incorporate scenario analysis into your decision.'
                },
                {
                    panel: 'round3Panel',
                    title: 'Round 3: Capital Structure Design',
                    brief: ''
                },
                {
                    panel: 'round4Panel',
                    title: 'Round 4: Working Capital Release & Board Presentation',
                    brief: 'Before the board presentation, your finance team has identified $12M of working capital trapped in sub-optimal operations. Select interventions to release cash, and address the disclosure question for any off-balance-sheet arrangements.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    cash: 40,
                    wacc: 0,
                    waccCorrect: 0,
                    creditRating: 'BBB-',
                    selectedOpps: [],
                    totalInvestment: 0,
                    netDebtEbitda: 2.8,
                    interestCoverage: 3.6,
                    wcReleased: 0,
                    disclosed: false,
                    totalScore: 0,
                    scoreHistory: [],
                    roundLabels: [],
                    eventMsg: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    equityBasis: 'book',
                    debtCost: 'coupon',
                    riskAdjust: 'no',
                    selectedOpps: [],
                    rankingMethod: 'irr',
                    scenarioAnalysis: 'base_only',
                    internalCash: 0,
                    newBond: 0,
                    revolver: 0,
                    convertible: 0,
                    equityIssue: 0,
                    wcRecv: false,
                    wcInv: false,
                    wcFact: false,
                    disclosure: false
                };
            }
            this._updateBriefing(state);
            this._updateRiskAdjustOptions();
            var self = this;
            setTimeout(function() { self._setupListeners(); self._updateRiskAdjustOptions(); }, 250);
            if (window.mySimulation && window.mySimulation.eventBus && !this.__riskOptsHooked) {
                this.__riskOptsHooked = true;
                window.mySimulation.eventBus.on('language:changed', function () { self._updateRiskAdjustOptions(); });
            }
        }

        validateDecisions(decisions) {
            var st = window.mySimulation.state;
            var round = st.currentPeriod;
            this._updateBriefing(st);

            if (round === 1) {
                var eqEl = document.getElementById('equityBasisSelect');
                var dtEl = document.getElementById('debtCostSelect');
                var raEl = document.getElementById('riskAdjustSelect');
                if (eqEl) decisions.equityBasis = eqEl.value;
                if (dtEl) decisions.debtCost = dtEl.value;
                if (raEl) decisions.riskAdjust = raEl.value;
                return true;
            }

            if (round === 2) {
                var opps = [];
                var ids = ['oppA','oppB','oppC','oppD','oppE'];
                for (var i = 0; i < ids.length; i++) {
                    var el = document.getElementById(ids[i]);
                    if (el && el.checked) opps.push(el.value);
                }
                decisions.selectedOpps = opps;
                var rmEl = document.getElementById('rankingMethodSelect');
                var scEl = document.getElementById('scenarioSelect');
                if (rmEl) decisions.rankingMethod = rmEl.value;
                if (scEl) decisions.scenarioAnalysis = scEl.value;
                if (opps.length === 0) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_no_investment'), 'warning'
                    );
                    return false;
                }
                return true;
            }

            if (round === 3) {
                var ic = document.getElementById('internalCashInput');
                var nb = document.getElementById('newBondInput');
                var rv = document.getElementById('revolverInput');
                var cv = document.getElementById('convertibleInput');
                var eq = document.getElementById('equityInput');
                decisions.internalCash = ic ? parseFloat(ic.value) || 0 : 0;
                decisions.newBond = nb ? parseFloat(nb.value) || 0 : 0;
                decisions.revolver = rv ? parseFloat(rv.value) || 0 : 0;
                decisions.convertible = cv ? parseFloat(cv.value) || 0 : 0;
                decisions.equityIssue = eq ? parseFloat(eq.value) || 0 : 0;

                var totalFin = decisions.internalCash + decisions.newBond + decisions.revolver + decisions.convertible + decisions.equityIssue;
                var needed = st.domainState.totalInvestment;
                if (totalFin < needed) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_financing_short') + ' $' + needed + 'M ' + window.mySimulation.t('warn_needed') + ', $' + totalFin.toFixed(1) + 'M ' + window.mySimulation.t('warn_provided') + '.', 'warning'
                    );
                    return false;
                }
                if (decisions.internalCash > 40) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_cash_limit'), 'warning'
                    );
                    return false;
                }
                return true;
            }

            if (round === 4) {
                var wr = document.getElementById('wcReceivables');
                var wi = document.getElementById('wcInventory');
                var wf = document.getElementById('wcFactoring');
                var dc = document.getElementById('disclosureCheck');
                decisions.wcRecv = wr ? wr.checked : false;
                decisions.wcInv = wi ? wi.checked : false;
                decisions.wcFact = wf ? wf.checked : false;
                decisions.disclosure = dc ? dc.checked : false;
                return true;
            }

            return true;
        }

        calculateResults(state) {
            var round = state.currentPeriod;
            var d = state.decisions;
            var ds = state.domainState;
            var score = 0;
            var roundName = '';
            var feedback = '';
            var _t = function(k) { try { return window.mySimulation.t(k); } catch (e) { return k; } };
            var _fill = function(tpl, map) {
                var out = tpl;
                for (var mk in map) { out = out.split('{' + mk + '}').join(String(map[mk])); }
                return out;
            };

            if (round === 1) {
                roundName = _t('rname_r1');
                var correct = 0;
                if (d.equityBasis === 'market') correct++;
                if (d.debtCost === 'ytm') correct++;
                if (d.riskAdjust === 'yes') correct++;

                var eqV = d.equityBasis === 'market' ? 220 : 95;
                var dV = 87;
                var tV = eqV + dV;
                var ke = 0.051 + 1.15 * 0.074;
                var kd = d.debtCost === 'ytm' ? 0.078 : 0.092;
                var wacc = (eqV / tV) * ke + (dV / tV) * kd * (1 - 0.35);
                ds.wacc = Math.round(wacc * 1000) / 10;
                ds.waccCorrect = correct;
                ds.r1 = { equityBasis: d.equityBasis, debtCost: d.debtCost, riskAdjust: d.riskAdjust };

                if (correct === 3) score = 20;
                else if (correct === 2) score = 13;
                else if (correct === 1) score = 7;
                else score = 0;

                feedback = _fill(_t('feedback_r1'), { correct: correct, wacc: ds.wacc });
                ds.eventMsg = window.mySimulation.t('event_tax_reform');
            }

            if (round === 2) {
                roundName = _t('rname_r2');
                var opps = d.selectedOpps || [];
                var totalCost = 0;
                var self = this;
                for (var i = 0; i < opps.length; i++) {
                    var opp = self.OPPS[opps[i]];
                    if (opp) totalCost += opp.cost;
                }
                ds.selectedOpps = opps.slice();
                ds.totalInvestment = totalCost;

                // value actually created, at risk-adjusted, probability-weighted NPVs
                var eSum = 0;
                for (var j = 0; j < opps.length; j++) { if (self.OPPS[opps[j]]) eSum += self.OPPS[opps[j]].eNpv; }
                // rival bid (concept event 2): a team anchored on one corporate WACC has no risk-adjusted
                // walk-away price for the acquisition and matches the bid with a USD 4M earn-out
                ds.overpaidB = false;
                if (opps.indexOf('B') >= 0 && !(ds.r1 && ds.r1.riskAdjust === 'yes')) { ds.overpaidB = true; eSum -= 4; }
                ds.portfolioValue = Math.round(eSum * 10) / 10;
                ds.r2 = { rankingMethod: d.rankingMethod, scenarioAnalysis: d.scenarioAnalysis };

                score = 0;
                if (d.rankingMethod === 'npv') score += 6;
                if (d.scenarioAnalysis === 'weighted') score += 3;
                var vFrac = (eSum - 4) / (self.BEST_VALUE - 4);
                score += Math.round(16 * Math.max(0, Math.min(1, vFrac)));
                score = Math.min(score, 25);

                feedback = _fill(_t('feedback_r2'), { opps: opps.join(', '), total: totalCost, method: d.rankingMethod.toUpperCase() });
                if (opps.indexOf('B') >= 0) {
                    ds.eventMsg = window.mySimulation.t('event_rival_bid') + ' ' + window.mySimulation.t(ds.overpaidB ? 'event_rival_matched' : 'event_rival_walkaway');
                } else {
                    ds.eventMsg = '';
                }
            }

            if (round === 3) {
                roundName = _t('rname_r3');
                var newDebt = d.newBond + d.revolver + d.convertible;
                var debtPaydown = 0;
                if (ds.selectedOpps.indexOf('C') >= 0) debtPaydown = 30;

                var cm = this._creditMetrics(ds.selectedOpps, d.newBond, d.revolver, d.convertible);
                var ndRatio = cm.nd;
                var intCov = cm.ic;

                ds.netDebtEbitda = Math.round(ndRatio * 100) / 100;
                ds.interestCoverage = Math.round(intCov * 10) / 10;
                ds.pfNetDebt = cm.netDebt;
                ds.pfEBITDA = cm.ebitda;

                var downgraded = cm.downgraded;
                ds.creditRating = downgraded ? 'BB+' : 'BBB-';
                ds.downgradedR3 = downgraded;
                ds.internalCash = d.internalCash;
                ds.r3 = { internalCash: d.internalCash, newBond: d.newBond, revolver: d.revolver, convertible: d.convertible, equityIssue: d.equityIssue, newDebt: newDebt };

                var need = ds.totalInvestment;
                var totalFin = d.internalCash + d.newBond + d.revolver + d.convertible + d.equityIssue;
                var target = Math.min(need, 40 - this.DRY_POWDER);
                var gap = Math.max(0, need - target);
                score = 0;
                // rating kept (trade-off theory: distress costs)
                if (!downgraded) score += 10;
                // the external gap funded with debt: tax shield captured without breaking the rating
                if (!downgraded) {
                    if (gap <= 2 || newDebt >= 0.75 * gap) score += 5;
                    else if (newDebt > 0) score += 3;
                }
                // pecking order: issuing equity signals overvaluation and dilutes (Myers-Majluf)
                score += Math.max(0, 5 - d.equityIssue / 3);
                // internal cash used first, keeping a dry-powder buffer
                score += Math.max(0, 5 - Math.abs(d.internalCash - target) / 2);
                // raising more than the plan needs costs carry
                score -= Math.min(5, Math.max(0, totalFin - need) / 2);
                score = Math.max(0, Math.min(25, Math.round(score)));
                ds.overRaised = Math.max(0, Math.round((totalFin - need) * 10) / 10);

                feedback = _fill(_t('feedback_r3'), { nd: ds.netDebtEbitda, cov: ds.interestCoverage, rating: ds.creditRating });
                if (ds.selectedOpps.indexOf('B') >= 0) {
                    ds.eventMsg = window.mySimulation.t('event_cfo_resign');
                } else {
                    ds.eventMsg = '';
                }
            }

            if (round === 4) {
                roundName = _t('rname_r4');
                var wcTotal = 0;
                var interventions = 0;
                if (d.wcRecv) { wcTotal += 4.2; interventions++; }
                if (d.wcInv) { wcTotal += 3.8; interventions++; }
                if (d.wcFact) { wcTotal += 4.0; interventions++; }
                ds.wcReleased = Math.round(wcTotal * 10) / 10;
                ds.disclosed = d.disclosure;

                ds.hiddenFactoring = !!(d.wcFact && !d.disclosure);
                ds.reclassDowngrade = false;
                ds.r4 = { wcRecv: !!d.wcRecv, wcInv: !!d.wcInv, wcFact: !!d.wcFact, disclosure: !!d.disclosure };
                var penalty = 0;
                // a disclosed supplier-finance programme is reclassified as debt by the rating agencies
                if (d.wcFact && d.disclosure && !ds.downgradedR3 && ds.pfEBITDA) {
                    var nd4 = ((ds.pfNetDebt || 87) + 4) / ds.pfEBITDA;
                    ds.netDebtEbitda = Math.round(nd4 * 100) / 100;
                    if (nd4 > this.ND_LIMIT) { ds.reclassDowngrade = true; ds.creditRating = 'BB+'; penalty += 16; }
                }
                // losing BBB- here costs what it costs in round 3: 10 rating points plus 6 of covenant review and refinancing
                // delayed cost of the round-3 downgrade: covenant review, +1.8pp on every refinancing
                if (ds.downgradedR3) penalty += 6;
                // hidden debt: auditors and agencies reclassify it later, and the board was not told
                if (ds.hiddenFactoring) penalty += 8;

                var opCash = (d.wcRecv ? 4.2 : 0) + (d.wcInv ? 3.8 : 0);
                var buffer = 40 - Math.min(40, ds.internalCash || 0) + opCash;
                ds.liquidityBuffer = Math.round(buffer * 10) / 10;

                score = 0;
                score += Math.min(Math.round(wcTotal / 12.0 * 12), 12);
                if (!ds.hiddenFactoring) score += 8;
                if (interventions >= 2) score += 5;
                else if (interventions >= 1) score += 2;
                score += buffer >= this.DRY_POWDER ? 5 : Math.round(buffer / this.DRY_POWDER * 5);
                score = Math.max(0, Math.min(30, score - penalty));

                ds.cash = Math.round((40 - Math.min(40, ds.internalCash || 0) + wcTotal) * 10) / 10;
                feedback = _fill(_t('feedback_r4'), { wc: ds.wcReleased, n: interventions, disclosed: _t(d.disclosure ? 'yes_label' : 'no_label') });
                ds.eventMsg = '';
            }

            ds.totalScore += score;
            ds.scoreHistory.push(score);
            ds.roundLabels.push(roundName);

            // overallScore mirrors getPerformanceSummary: totalScore already sums the four
            // round maxes (20+25+25+30) to 100, so the running cumulative score is 0-100 as is
            var overallScore = Math.max(0, Math.min(100, Math.round(ds.totalScore)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var adapter = this;
            var nextPeriod = round + 1;
            setTimeout(function() {
                if (nextPeriod <= adapter.ROUNDS.length) {
                    adapter._updateBriefing({ currentPeriod: nextPeriod, domainState: ds });
                }
            }, 500);

            return {
                period: state.currentPeriod,
                roundName: roundName,
                score: score,
                totalScore: ds.totalScore,
                overallScore: overallScore,
                feedback: feedback,
                creditRating: ds.creditRating,
                wacc: ds.wacc
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', (v) => '$' + v + 'M');
            uiManager.bind('ratingDisplay', 'domainState.creditRating');
            uiManager.bind('waccDisplay', 'domainState.wacc', (v) => v > 0 ? v + '%' : '--');
            uiManager.bind('scoreDisplay', 'domainState.totalScore', (v) => v + ' / 100');
        }

        getChartConfig() {
            var _tcc = function(k, d) { try { return window.mySimulation.t(k); } catch (e) { return d; } };
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: _tcc('chart_score_dataset', 'Score per Round'),
                            data: [],
                            backgroundColor: ['#2c3e50', '#2b6cb0', '#276749', '#b7791f'],
                            borderColor: ['#1a252f', '#1e4e8c', '#1a5632', '#975a16'],
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: _tcc('chart_score_title', 'Score by Round') },
                            legend: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                max: 30,
                                title: { display: true, text: _tcc('chart_points_axis', 'Points') }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            return {
                scoreChart: {
                    labels: state.domainState.roundLabels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                }
            };
        }

        _lang() {
            try { if (window.vcI18n && window.vcI18n._lang) return window.vcI18n._lang; } catch (e) {}
            var h = document.documentElement && document.documentElement.lang;
            return h ? String(h).slice(0, 2) : 'en';
        }

        _fmt(v, dec) {
            return Number(v || 0).toFixed(dec == null ? 1 : dec);
        }

        _tx(k, map) {
            var out;
            try { out = window.mySimulation.t(k); } catch (e) { out = k; }
            for (var mk in (map || {})) { out = out.split('{' + mk + '}').join(String(map[mk])); }
            return out;
        }

        /* Debrief built from the run itself: what this player chose, what it cost, and the round where it broke. */
        _debrief(history) {
            var ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var self = this;
            var sc = [];
            for (var i = 0; i < 4; i++) sc.push(history[i] && history[i].results ? (history[i].results.score || 0) : 0);
            var maxes = [20, 25, 25, 30];
            var ins = [];
            var breaks = [];
            var r1 = ds.r1 || {}, r2 = ds.r2 || {}, r3 = ds.r3 || {}, r4 = ds.r4 || {};
            // round 1
            if (r1.equityBasis === 'book' || r1.debtCost === 'coupon') {
                var parts = [];
                if (r1.equityBasis === 'book') parts.push(self._tx('db_book'));
                if (r1.debtCost === 'coupon') parts.push(self._tx('db_coupon'));
                ins.push(self._tx('db_r1_inputs', { what: parts.join(self._tx('db_and')), wacc: self._fmt(ds.wacc) }));
                breaks.push({ r: 1, k: 'db_tp_r1' });
            } else if (history.length >= 1) {
                ins.push(self._tx('db_r1_ok', { wacc: self._fmt(ds.wacc) }));
            }
            if (r1.riskAdjust === 'no') {
                ins.push(self._tx(ds.overpaidB ? 'db_onerate_paid' : 'db_onerate'));
                breaks.push({ r: ds.overpaidB ? 2 : 1, k: 'db_tp_onerate' });
            }
            // round 2
            var opps = ds.selectedOpps || [];
            var best = self.BEST_VALUE;
            if (history.length >= 2) {
                if (r2.rankingMethod === 'irr') {
                    ins.push(self._tx('db_irr', { v: self._fmt(ds.portfolioValue), best: self._fmt(best) }));
                    breaks.push({ r: 2, k: 'db_tp_irr' });
                } else {
                    ins.push(self._tx('db_value', { v: self._fmt(ds.portfolioValue), best: self._fmt(best) }));
                    if ((ds.portfolioValue || 0) < 0.85 * best) breaks.push({ r: 2, k: 'db_tp_value' });
                }
                if (r2.scenarioAnalysis === 'base_only') ins.push(self._tx('db_baseonly'));
                if (opps.indexOf('D') >= 0 || opps.indexOf('C') >= 0) ins.push(self._tx('db_nonvalue'));
            }
            // round 3
            if (history.length >= 3) {
                if (ds.downgradedR3) {
                    ins.push(self._tx('db_levered', { nd: self._fmt(ds.netDebtEbitda, 2), debt: self._fmt(r3.newDebt, 0) }));
                    breaks.push({ r: 3, k: 'db_tp_levered' });
                } else if ((r3.newDebt || 0) > 0) {
                    ins.push(self._tx('db_r3_ok', { debt: self._fmt(r3.newDebt || 0, 0) }));
                } else {
                    ins.push(self._tx('db_r3_nodebt'));
                }
                if ((r3.equityIssue || 0) > 0) { ins.push(self._tx('db_equity', { eq: self._fmt(r3.equityIssue, 0) })); breaks.push({ r: 3, k: 'db_tp_equity' }); }
                if ((ds.overRaised || 0) > 0) ins.push(self._tx('db_overraised', { x: self._fmt(ds.overRaised) }));
            }
            // round 4
            if (history.length >= 4) {
                if (ds.hiddenFactoring) { ins.push(self._tx('db_hidden')); breaks.push({ r: 4, k: 'db_tp_hidden' }); }
                else if (ds.reclassDowngrade) { ins.push(self._tx('db_reclass', { nd: self._fmt(ds.netDebtEbitda, 2) })); breaks.push({ r: 4, k: 'db_tp_reclass' }); }
                else ins.push(self._tx('db_r4_ok', { wc: self._fmt(ds.wcReleased) }));
                if ((ds.liquidityBuffer || 0) < self.DRY_POWDER) ins.push(self._tx('db_nobuffer', { b: self._fmt(ds.liquidityBuffer) }));
            }
            // turning point: the round with the largest share of its points lost, among rounds where a named mistake sits
            var tp = null;
            if (breaks.length) {
                var worst = -1;
                for (var b = 0; b < breaks.length; b++) {
                    var lost = 1 - sc[breaks[b].r - 1] / maxes[breaks[b].r - 1];
                    if (breaks[b].k === 'db_tp_hidden' || breaks[b].k === 'db_tp_onerate') lost += 0.2;
                    if (lost > worst) { worst = lost; tp = breaks[b]; }
                }
            }
            var process = sc[0] + (r2.rankingMethod === 'npv' ? 6 : 0) + (r2.scenarioAnalysis === 'weighted' ? 3 : 0);
            return { insights: ins.slice(0, 6), turningRound: tp ? tp.r : 0, turning: tp ? self._tx('db_tp_prefix', { r: tp.r }) + ' ' + self._tx(tp.k) : self._tx('db_tp_none'), process: process };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var total = 0;
            for (var i = 0; i < history.length; i++) {
                total += (history[i].results ? history[i].results.score || 0 : 0);
            }
            total = Math.max(0, Math.min(100, Math.round(total)));
            var pct = total;
            var tier = 'insufficient';
            if (pct >= 90) tier = 'excellent';
            else if (pct >= 70) tier = 'competent';
            else if (pct >= 50) tier = 'developing';
            var label = this._tx('perf_' + tier);
            var db = this._debrief(history);
            var ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};

            return {
                totalScore: total,
                overallScore: total,
                composite: total,
                score: total,
                maxScore: 100,
                percentage: pct,
                performance: tier,
                performanceKey: tier,
                performanceLabel: label,
                processScore: Math.min(29, db.process),
                outcomeScore: Math.max(0, total - Math.min(29, db.process)),
                turningPoint: db.turning,
                turningRound: db.turningRound,
                insights: db.insights,
                questions: [this._tx('db_q1'), this._tx('db_q2'), this._tx('db_q3')],
                kpis: { wacc: ds.wacc, value: ds.portfolioValue, rating: ds.creditRating, nd: ds.netDebtEbitda, wc: ds.wcReleased }
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var self = this;
            var k = summary.kpis || {};
            var li = function (arr) { var h = ''; for (var i = 0; i < (arr || []).length; i++) h += '<li>' + arr[i] + '</li>'; return h; };
            var kpi = function (lab, val) { return '<div class="cfo-sim-cm-kpi"><span class="cfo-sim-cm-kpi-l">' + lab + '</span><strong>' + val + '</strong></div>'; };
            return '<div class="cfo-sim-cm" role="status" aria-live="polite">'
                + '<div class="cfo-sim-cm-score"><strong>' + (summary.overallScore || 0) + '</strong> / 100 <span class="cfo-sim-cm-tier">' + (summary.performanceLabel || '') + '</span></div>'
                + '<p class="cfo-sim-cm-sub">' + self._tx('db_sub', { o: summary.outcomeScore || 0, p: summary.processScore || 0 }) + '</p>'
                + '<div class="cfo-sim-cm-kpis">'
                + kpi(self._tx('wacc_label'), self._fmt(k.wacc) + '%')
                + kpi(self._tx('db_kpi_value'), '$' + self._fmt(k.value) + 'M')
                + kpi(self._tx('rating_label'), k.rating || '--')
                + kpi(self._tx('db_kpi_nd'), self._fmt(k.nd, 2) + 'x')
